export function getPostBySlug(slug) {
  return blogPosts.find(p => p.slug === slug)
}

export function getFeaturedPost() {
  return getPostBySlug(featuredSlug)
}

export function getPopularPosts() {
  return popularSlugs.map(slug => getPostBySlug(slug)).filter(Boolean)
}

export function getPostsByCategory(categoryId) {
  if (categoryId === 'all') return blogPosts
  return blogPosts.filter(p => p.category === categoryId)
}

export function getRelatedPosts(currentSlug, limit = 3) {
  const current = getPostBySlug(currentSlug)
  if (!current) return []
  return blogPosts
    .filter(p => p.slug !== currentSlug && p.category === current.category)
    .slice(0, limit)
}

export function getCategoryLabel(categoryId) {
  const cat = blogCategories.find(c => c.id === categoryId)
  return cat ? cat.label : categoryId
}

export function getBlogBreadcrumbs(postSlug) {
  if (!postSlug) {
    return [
      { name: 'Home', path: '/' },
      { name: 'Blog', path: '/blog' },
    ]
  }
  const post = getPostBySlug(postSlug)
  return [
    { name: 'Home', path: '/' },
    { name: 'Blog', path: '/blog' },
    { name: post ? post.title : postSlug.replace(/-/g, ' '), path: `/blog/${postSlug}` },
  ]
}
